/**
 * The stadium round the field (docs/visuals/REWORK.md, stadium module): a steel cage with hex wire
 * netting on the shell and the flat roof, dim LED boards along the wall base, banners with
 * procedural emblems hung on the cage, stands with an instanced crowd along both side walls, and
 * eight floodlight towers with hot lamp heads, a tight glare and (ultra) beams. ArenaView builds it
 * and disposes it; everything is generated by code at build time (geometry, canvas textures).
 *
 *   netting.ts      shell above the board band + roof: the cage netting (transparent)
 *   boards.ts       shell below it: ramp pad, LED boards, rail, goal-module surrounds (opaque, lit)
 *   steel.ts        arches, ribs, rings, roof beams, floodlight towers (one merged lit mesh)
 *   floodlights.ts  lamp panels, glare sprites, beams
 *   stands.ts       stand structure and crowd
 *   banners.ts      the hanging banners
 *   textures.ts     the board and banner canvas atlases
 *   palette.ts      the per-theme uniforms (a theme switch only writes uniforms and a vertex
 *                   attribute of the lamp meshes: never a recompile)
 *   layout.ts       where everything stands (pure numbers, tested in node)
 *   geometry.ts     the shell split and the tube / merge helpers
 *
 * Draw calls: netting 1, boards 1, steel 1, lamp panels 1, glare 1, stand structure 1, crowd 1,
 * banners 1 = 8, + beams 1 with `beamCones` (ultra) = 9. Nothing casts shadows. Nothing changes per
 * frame on the CPU: the board cards, crowd wave, flashes and banner wind run on the GPU clock.
 *
 * Transparent order: the netting draws first among the transparents (renderOrder -5, before the
 * goals at -4); the glare and beams (additive, renderOrder 0) are sorted with the other
 * renderOrder-0 transparents. Every unlit or transparent material sets glowMrt / noGlowMrt
 * (materials.ts). Nothing starts hidden (lamps off by day are drawn at zero intensity), so there is
 * nothing to warm up.
 */
import * as THREE from 'three/webgpu';
import { tier, type Quality } from '../quality';
import type { ThemeId } from '../theme';
import { buildBanners } from './banners';
import { buildBoardMaterial } from './boards';
import { buildBeams, buildGlare, buildLampPanels, type HeadMesh } from './floodlights';
import { splitShell } from './geometry';
import { buildNetMaterial } from './netting';
import { applyStadiumTheme, createStadiumUniforms, type StadiumUniforms } from './palette';
import { buildCrowd, buildStandGeometry, buildStandMaterial } from './stands';
import { buildSteelGeometry, buildSteelMaterial } from './steel';
import { bannerAtlas, boardAtlas } from './textures';

interface Disposable {
  dispose(): void;
}

/** The sim's wall shell and flat ceiling in three coords (owned and disposed by the view). */
export interface StadiumGlass {
  readonly shell: THREE.BufferGeometry;
  readonly ceiling: THREE.BufferGeometry;
}

export class StadiumView {
  /** The cage netting: the shell above the board band and the roof, one transparent mesh. */
  readonly shell: THREE.Mesh;
  /** The roof is part of the netting mesh (one draw): the same mesh as `shell`. */
  readonly ceiling: THREE.Mesh;
  /** The board band (the shell below the netting). */
  readonly boards: THREE.Mesh;

  private readonly u: StadiumUniforms;
  private readonly heads: HeadMesh[] = [];
  private readonly disposables: Disposable[] = [];

  /** Build the stadium for a tier and a theme into `parent`; it takes ownership of the glass geometries. */
  constructor(parent: THREE.Object3D, glass: StadiumGlass, quality: Quality, theme: ThemeId) {
    const spec = tier(quality);
    this.u = createStadiumUniforms();

    // ---- Shell: netting above the board band (with the roof), boards below ------------------
    const { boards, net } = splitShell(glass.shell, glass.ceiling);
    glass.shell.dispose();
    glass.ceiling.dispose();
    const atlas = boardAtlas(spec.detail === 'high' ? 1024 : 512);
    this.boards = this.add(parent, new THREE.Mesh(boards, buildBoardMaterial(spec, this.u, atlas)), 'stadium-boards');
    this.track(atlas);
    this.shell = this.add(parent, new THREE.Mesh(net, buildNetMaterial(spec, this.u)), 'stadium-netting');
    this.shell.renderOrder = -5;
    this.ceiling = this.shell;

    // ---- Steel cage and towers (1) -----------------------------------------------------------
    this.add(parent, new THREE.Mesh(buildSteelGeometry(spec).geometry, buildSteelMaterial(this.u)), 'stadium-steel');

    // ---- Floodlights: lamp panels, glare (+ beams on ultra) ---------------------------------
    const lights = [buildLampPanels(this.u), buildGlare(spec, this.u)];
    if (spec.beamCones) lights.push(buildBeams(this.u));
    for (const h of lights) {
      this.add(parent, h.mesh);
      this.heads.push(h);
    }

    // ---- Stands and crowd (2) ------------------------------------------------------------------
    this.add(parent, new THREE.Mesh(buildStandGeometry(), buildStandMaterial(this.u)), 'stadium-stands');
    this.add(parent, buildCrowd(spec, this.u).mesh);

    // ---- Banners (1) -----------------------------------------------------------------------------
    const bannerTex = bannerAtlas(spec.detail === 'high' ? 256 : 128);
    this.add(parent, buildBanners(spec, bannerTex).mesh);
    this.track(bannerTex);

    this.setTheme(theme);
  }

  /** The stadium theme changed: uniform writes and the lamp meshes' strength attribute only. */
  setTheme(theme: ThemeId): void {
    const strengths = applyStadiumTheme(this.u, theme);
    for (const h of this.heads) h.setStrengths(strengths);
  }

  /**
   * Pipeline warm-up (Game.setWarm): make meshes that start hidden renderable while `on`, so their
   * shaders compile behind the boot overlay. Nothing here starts hidden (lamps that are off by day
   * still draw, at zero intensity).
   */
  setWarmUp(on: boolean): void {
    void on;
  }

  /** Free every geometry, material and texture (the parent removes the meshes from the scene). */
  dispose(): void {
    for (const d of this.disposables) d.dispose();
    this.disposables.length = 0;
  }

  private track(...items: Disposable[]): void {
    for (const d of items) this.disposables.push(d);
  }

  /** Static mesh: no shadows, no matrix updates, never culled (it surrounds the camera). */
  private add<T extends THREE.Mesh>(parent: THREE.Object3D, mesh: T, name?: string): T {
    if (name !== undefined) mesh.name = name;
    mesh.castShadow = false;
    mesh.receiveShadow = false;
    mesh.matrixAutoUpdate = false;
    mesh.frustumCulled = false;
    this.track(mesh.geometry, mesh.material as THREE.Material);
    // An InstancedMesh owns its instance matrices (freed by its own dispose).
    if (mesh instanceof THREE.InstancedMesh) this.track(mesh);
    parent.add(mesh);
    return mesh;
  }
}
